function nav(){const pages=[['start','Startseite','⌂'],['profile','Persönliche Daten','♙'],['gdb','GdB & Teilhabe','§'],['analysis','Gesundheitsanalyse','▣'],['pro','Analyse Pro','◈'],['prevention','Vorsorge & Notfallplan','◷'],['symptoms','Symptome','☷'],['medlog','Einnahmeprotokoll','✚'],['reminders','Kontrollen','◷'],['evidence','GdB-Nachweise','▤'],['glucose','Blutzucker','◆'],['bp','Blutdruck','♥'],['weight','Körpergewicht','⚖'],['labs','Laborwerte','⊕'],['meds','Medikamente','✚'],['emergency','Notfallpass','!'],['stats','Statistiken','▤'],['benefits','Leistungen','§'],['settings','Backup & Updates','⚙']];return `<div class="nav-shell"><details class="nav-disclosure"><summary class="nav-toggle"><span class="nav-toggle-title">☷ &nbsp; Bereiche öffnen</span><span class="nav-toggle-current">${h(pages.find(p=>p[0]===view)?.[1]||'Startseite')}</span></summary><nav class="nav" aria-label="Hauptnavigation"><div class="nav-guide" aria-hidden="true"><strong>Deine Bereiche</strong><span class="nav-guide-chip guide-mess">Messwerte</span><span class="nav-guide-chip guide-analysis">Auswertung</span><span class="nav-guide-chip guide-care">Behandlung & Vorsorge</span><span class="nav-guide-chip guide-admin">Verwaltung</span></div>${pages.map(([v,t,i])=>`<button type="button" data-view="${v}" aria-current="${v===view?'page':'false'}"><span aria-hidden="true">${i}</span> ${t}</button>`).join('')}</nav></details></div>`}
