function renderMain(){if(!data){return}const main=$('#main');main.dataset.section=view;const content={start:pageStart,profile:pageProfile,gdb:pageGdb,analysis:pageAnalysis,pro:pagePro,prevention:pagePrevention,symptoms:pageSymptoms,medlog:pageMedLog,reminders:pageReminders,evidence:pageEvidence,glucose:pageGlucose,bp:pageBp,weight:pageWeight,labs:pageLabs,meds:pageMeds,emergency:pageEmergency,stats:pageStats,benefits:pageBenefits,settings:pageSettings};$('#main').innerHTML=(content[view]||pageStart)();formatMobileTables($('#main'))}
